{-# LANGUAGE EmptyCase #-}
import Data.Void
after :: Void -> a
after x = case x of {}

class Last {
  int keep() {
    try { return 1; }
    finally { return 0; }
  }
}

procedure Still is
   subtype Heartbeat is Integer range 1 .. 1;
   Pulse : Heartbeat := 1;
begin
   Pulse := Pulse + 1;
end Still;
